/* Dry-run runtime for assembly generated by il2asm.nsis. */
#ifndef IL2ASM_NSIS_H
#define IL2ASM_NSIS_H

const char *shim_nsis_concat(const char *a, const char *b);
int shim_nsis_compare(const char *a, const char *op, const char *b);

long shim_nsis_set_out_path(const char *path);
long shim_nsis_mkdir(const char *path);
long shim_nsis_rmdir(const char *flags, const char *path);
long shim_nsis_delete(const char *path);
long shim_nsis_file(const char *flags, const char *pattern);
long shim_nsis_ini_write(const char *path, const char *section,
                         const char *key, const char *value);
long shim_nsis_reg_write(const char *root, const char *key,
                         const char *name, const char *value);
long shim_nsis_reg_delete_key(const char *root, const char *key);
long shim_nsis_shortcut(const char *link, const char *target);
long shim_nsis_write_uninstaller(const char *path);
long shim_nsis_set_attrs(const char *path, const char *attrs);
long shim_nsis_set_overwrite(const char *mode);
long shim_nsis_set_autoclose(const char *mode);
long shim_nsis_hide_window(void);
long shim_nsis_message_box(const char *flags, const char *text);
long shim_nsis_abort(void);
long shim_nsis_exec(const char *command);
long shim_nsis_system_call(const char *signature);
long shim_nsis_unimplemented(const char *line);

unsigned long shim_nsis_action_count(void);

#endif
